static long mergeCost(int[] a) {
    var pq = new PriorityQueue<Long>();
    for (int v : a) pq.add((long) v);
    long cost = 0;
    while (pq.size() > 1) {
        long x = pq.poll(), y = pq.poll();
        cost += x + y;
        pq.add(x + y);
    }
    return cost;
}

// MinHeap: 직접 만든 최소 힙 클래스
function mergeCost(a) {
  const h = new MinHeap();
  for (const v of a) h.push(v);
  let cost = 0;
  while (h.size() > 1) {
    const x = h.pop(), y = h.pop();
    cost += x + y;
    h.push(x + y);
  }
  return cost;
}

long long mergeCost(const vector<int>& a) {
    priority_queue<long long, vector<long long>,
        greater<>> pq(a.begin(), a.end());
    long long cost = 0;
    while (pq.size() > 1) {
        long long x = pq.top(); pq.pop();
        long long y = pq.top(); pq.pop();
        cost += x + y;
        pq.push(x + y);
    }
    return cost;
}
